# Prints "true" if the pull request changes anything that goes into the binaries (and so needs the 'Pull Request' build), else
# "false". Looks at every file the whole pull request changes against its base, not at the latest commit. When the files can not
# be listed it prints "true", so a build is never skipped by mistake.
#
# Usage: pr-needs-build.sh <pull request number>      (needs GH_TOKEN and GH_REPO)
set -u

NUMBER="${1:?pull request number}"

FILES="$(gh api --paginate "repos/${GH_REPO}/pulls/${NUMBER}/files" --jq '.[] | .filename, (.previous_filename // empty)')" || { echo true; exit 0; }
[ -n "$FILES" ] || { echo true; exit 0; }

# Only what changes the binaries. Documentation, the wiki, the tests and the tools do not.
if printf '%s\n' "$FILES" | grep -q -E '^(code_compiler/|code_runtime/|cmake/|third_party/|CMakeLists\.txt$|CMakePresets\.json$|\.gitmodules$|LICENSE\.adoc$|\.github/scripts/check-licenses\.sh$|\.github/workflows/pull-request\.yml$)'; then
  echo true
else
  echo false
fi
